@startuml

enum RoomType {
  SINGLE
  DOUBLE
  TWIN
}

enum PaymentType {
  PREPAID
  PAID_AT_HOTEL
}

class HotelBookingManager {}

class Traveller {
  + name : string
  + reliabilityRating : float
}

class BillingInformation {
  + companyName : string
  + address : string
}

class TravelPreference {
  + preference : string
}

class SearchInfo {
  + city : string
  + arrivalDate : date
  + departureDate : date
  + numberOfRooms : int
  + roomType : RoomType
  + minimumHotelRating : int
  + tentativeBudget : float
}

class Booking {
  + bookingId : int
  + creditCardInformation : string
  + cancellationDeadline : date
  + isConfirmed : boolean
  + paymentType : PaymentType
}

class PreliminaryBookingInfo {
  + price : float
  + cityArea : string
  + hotelRating : int
}

class SpecialOffer {
  + price : float
}

class Hotel {
  + address : string
  + city : string
}

class HotelChain {}

class RoomAvailability {
  + isFullyBooked : boolean
}

Traveller "1" -- "1" BillingInformation
Traveller "1" -- "*" TravelPreference
Traveller "1" -- "*" SearchInfo
Traveller "1" -- "*" Booking
HotelBookingManager "1" -- "*" Traveller
HotelBookingManager "1" -- "*" Booking
HotelBookingManager "1" -- "*" Hotel
HotelBookingManager "1" -- "*" SpecialOffer

Hotel "1" -- "*" HotelChain
Hotel "1" -- "*" Booking
Hotel "1" -- "*" SpecialOffer
Hotel "1" -- "*" RoomAvailability

Booking "0..1" -- "1" PreliminaryBookingInfo
PreliminaryBookingInfo "1" -- "*" SpecialOffer
PreliminaryBookingInfo "1" -- "1" SearchInfo

@enduml

